// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/orders", wrapper.RazorpayOrdersList)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/orders", wrapper.RazorpayOrdersCreate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/orders/{id}", wrapper.RazorpayOrdersFetch)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/orders/{id}/payments", wrapper.RazorpayOrdersFetchPayments)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/payments", wrapper.RazorpayPaymentsList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/payments/{id}", wrapper.RazorpayPaymentsFetch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/payments/{id}/refund", wrapper.RazorpayPaymentsRefund)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/payments/{id}/refunds", wrapper.RazorpayPaymentsFetchRefunds)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/refunds", wrapper.RazorpayRefundsList)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/refunds/{id}", wrapper.RazorpayRefundsFetch)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/payment_links", wrapper.RazorpayPaymentLinksList)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/payment_links", wrapper.RazorpayPaymentLinksCreate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/payment_links/{id}", wrapper.RazorpayPaymentLinksFetch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/payment_links/{id}/cancel", wrapper.RazorpayPaymentLinksCancel)

	return m
}

